practice_challenges.starter_code:
def parse(s):
    if s == "":
        raise ValueError("empty")
    return int(s)

def run_all(items):
    results, errors = [], []
    for item in items:
        try:
            results.append(parse(item))
        except Exception as exc:
            errors.append(exc)
    if errors:
        raise ExceptionGroup("batch failed", errors)
    return results

def summarize(items):
    """Return (number of ValueErrors, number of TypeErrors) raised by run_all(items), using except*."""
    n_value = n_type = 0
    # try: run_all(items)
    # except* ValueError as group: n_value = len(group.exceptions)
    # except* TypeError as group: n_type = ...
    return n_value, n_type

print(summarize(["1", "", "x", None, "5"]))

uth_example:
def check(name, value):
    if value < 0:
        raise ValueError(f"{name} is negative")
    if value > 100:
        raise OverflowError(f"{name} is too big")

errors = []
for name, value in {"a": -1, "b": 50, "c": 500, "d": -9}.items():
    try:
        check(name, value)
    except Exception as exc:
        errors.append(exc)

try:
    raise ExceptionGroup("validation", errors)
except* ValueError as group:
    print("value:", [str(e) for e in group.exceptions])
except* OverflowError as group:
    print("overflow:", [str(e) for e in group.exceptions])

